<script setup lang="ts">
import {onMounted,onBeforeUnmount,reactive,ref,computed,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
import ProviderMappingEditor from '../components/ProviderMappingEditor.vue'
import ProviderTestDialog from '../components/ProviderTestDialog.vue'
import type {ProtocolRoute,ProviderDraftMapping} from '../api/provider'
import {type Provider,type ProviderType,type TestResult,healthLabels,authLabels,schedulingLabels,categoryLabels,protocolNames} from '../api/provider'
const rows=ref<Provider[]>([]),types=ref<ProviderType[]>([]),page=ref(1),total=ref(0),q=ref(''),status=ref(''),providerType=ref(''),protocol=ref(''),health=ref(''),loading=ref(false),saving=ref(false),error=ref(''),dialog=ref(false),editing=ref<number|null>(null),hasKey=ref(false),testing=ref<number|null>(null),testResult=ref<TestResult|null>(null)
const advanced=ref(false)
const category=ref(''),testDialog=ref(false),testAccount=ref<Provider|null>(null),verifyAfterSave=ref(false),autoTest=ref(false)
const visibleColumns=ref(['models','priority','concurrency','health','latency','key'])
const columnOptions={models:'模型',priority:'优先级',concurrency:'最大并发',health:'健康 / 调度',latency:'最近延迟',key:'Key'}
const plans=computed(()=>selectedType.value?.account_types||{standard:{name:form.provider_type==='zhipu_coding_plan'?'Coding Plan':'标准账号',base_url:selectedType.value?.base_url||''}})
const availableCategories=computed(()=>{const ops=selectedType.value?.operations;return Object.entries(categoryLabels).filter(([k])=>k!=='mixed'&&(!ops||(['text','multimodal'].includes(k)?ops.some(o=>['chat','messages','responses'].includes(o)):k==='image'?ops.includes('images'):ops.some(o=>['embeddings','rerank'].includes(o)))))})
const availableProtocols=computed(()=>form.protocol_type==='image'?['openai-images']:form.protocol_type==='vector'?['openai-embeddings',...(form.provider_type==='custom_openai'?['openai-rerank']:[])]:['openai-completions','openai-responses','anthropic-messages'])
const mappings=ref<ProviderDraftMapping[]>([]),mappingLoading=ref(false),mappingsReady=ref(false),discovering=ref(false),discovered=ref<string[]>([]),editorVersion=ref<number|null>(null)
const protocolOptions=computed(()=>Array.from(new Set([...availableProtocols.value,...selectedProtocols.value])))
const selectedProtocols=ref<string[]>(['openai-completions','openai-responses'])
const routes=reactive<Record<string,ProtocolRoute>>({})
const testModels=computed(()=>mappings.value.filter(m=>m.status==='enabled'&&m.logical_model.trim()).map(m=>({...m,logical_model:m.logical_model.trim(),upstream_model:m.upstream_model.trim()})))
const originalProvider=ref<Provider|null>(null),originalProtocols=ref<string[]>([])
const separateUrls=ref(false),protocolUrls=reactive<Record<string,string>>({})
function syncProtocols(){if(selectedProtocols.value.includes('ollama')&&selectedProtocols.value.length>1){selectedProtocols.value=[selectedProtocols.value.at(-1)==='ollama'?'ollama':selectedProtocols.value.filter(p=>p!=='ollama')[0]!]}for(const p of selectedProtocols.value){if(!routes[p])routes[p]={path_prefix:'',auth_type:p==='anthropic-messages'?'x-api-key':'bearer'};if(!protocolUrls[p])protocolUrls[p]=form.base_url}}
function unchangedConnection(){const p=originalProvider.value;if(!p)return false;const names=p.protocol_config?Object.keys(p.protocol_config):originalProtocols.value;return names.length===selectedProtocols.value.length&&selectedProtocols.value.every(name=>{const r:ProtocolRoute=p.protocol_config?p.protocol_config[name]:{path_prefix:'',auth_type:p.protocol==='anthropic'?'x-api-key':'bearer'};return !!r&&r.auth_type===routes[name]?.auth_type&&(r.api_url||p.base_url.replace(/\/$/,'')+(r.path_prefix||'')).replace(/\/$/,'')===(separateUrls.value?protocolUrls[name]||'':form.base_url).trim().replace(/\/$/,'')})}
function connectionBaseUrl(){return unchangedConnection()?originalProvider.value!.base_url:form.base_url.trim()}
function connectionConfig(){if(unchangedConnection())return {protocol:originalProvider.value!.protocol,protocol_config:originalProvider.value!.protocol_config};const first=selectedProtocols.value[0];return {protocol:first==='anthropic-messages'?'anthropic':first==='ollama'?'ollama':'openai',protocol_config:Object.fromEntries(selectedProtocols.value.map(p=>[p,{path_prefix:'',auth_type:routes[p]!.auth_type,...(separateUrls.value?{api_url:protocolUrls[p]?.trim()}: {})}]))}}
function loadProtocols(p?:Provider){
  for(const k of Object.keys(routes))delete routes[k]
  for(const k of Object.keys(protocolUrls))delete protocolUrls[k]
  separateUrls.value=false
  if(p?.protocol_config){
    selectedProtocols.value=Object.keys(p.protocol_config)
    for(const [name,config] of Object.entries(p.protocol_config)){routes[name]={path_prefix:'',auth_type:config.auth_type};protocolUrls[name]=config.api_url||p.base_url.replace(/\/$/,'')+(config.path_prefix||'')}
    form.base_url=protocolUrls[selectedProtocols.value[0]!]||p.base_url
    separateUrls.value=selectedProtocols.value.some(name=>protocolUrls[name]!==form.base_url)
  }else{
    const proto=p?.protocol||form.protocol
    selectedProtocols.value=proto==='anthropic'?['anthropic-messages']:proto==='ollama'?['ollama']:form.protocol_type==='image'?['openai-images']:form.protocol_type==='vector'?['openai-embeddings']:selectedType.value?.operations&&!selectedType.value.operations.includes('responses')?['openai-completions']:['openai-completions','openai-responses']
  }
  syncProtocols()
}
function toggleSeparateUrls(){if(separateUrls.value)for(const p of selectedProtocols.value)protocolUrls[p]=form.base_url}
function validateUrls(){
  const values=[form.base_url,...(separateUrls.value?selectedProtocols.value.map(p=>protocolUrls[p]||''):[])]
  for(const value of values){try{const u=new URL(value.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash||/[\s\\]/.test(value.trim()))throw new Error()}catch{ElMessage.error('请填写完整的 HTTP/HTTPS API 地址，不含凭据、查询参数或片段');return false}}
  return true
}
const blank=()=>({name:'',provider_type:'openai',protocol:'openai',protocol_type:'text' as string|null,account_type:'standard',base_url:'https://api.openai.com/v1',api_key:'',clear_api_key:false,proxy:'',priority:0,max_concurrency:10,status:'enabled',remark:'',default_test_model:''})
const form=reactive(blank()),selectedType=computed(()=>types.value.find(t=>t.code===form.provider_type))
function typeName(code:string){return types.value.find(t=>t.code===code)?.name||code}
let loadGeneration=0,openGeneration=0
async function load(){const gen=++loadGeneration;loading.value=true;error.value='';try{const d=(await api.get('/admin/providers',{params:{page:page.value,q:q.value,status:status.value,provider_type:providerType.value,protocol:protocol.value,protocol_type:category.value,health_status:health.value}})).data.data;if(gen!==loadGeneration)return;rows.value=d.items;total.value=d.total}catch(e){if(gen===loadGeneration)error.value=message(e)}finally{if(gen===loadGeneration)loading.value=false}}
async function open(p?:Provider&{config_version?:number}){
  const gen=++openGeneration;verifyAfterSave.value=false;mappingLoading.value=false
  editing.value=p?.id??null;editorVersion.value=p?.config_version??null;hasKey.value=p?.has_api_key||false
  Object.assign(form,blank(),p?{name:p.name,provider_type:p.provider_type,protocol:p.protocol,protocol_type:p.protocol_type,account_type:p.account_type,base_url:p.base_url,proxy:p.proxy||'',priority:p.priority,max_concurrency:p.max_concurrency,status:p.status,remark:p.remark,default_test_model:p.default_test_model||''}:{})
  originalProvider.value=p||null;loadProtocols(p);originalProtocols.value=[...selectedProtocols.value]
  mappings.value=[{logical_model:'',upstream_model:'',model_type:form.protocol_type==='multimodal'?'multimodal':form.protocol_type==='image'?'image':form.protocol_type==='vector'?'embedding':'text',status:'enabled'}];discovered.value=[];mappingsReady.value=!p;dialog.value=true
  if(p){mappingLoading.value=true;try{const rows=(await api.get('/admin/providers/'+p.id+'/model-mappings')).data.data;if(gen!==openGeneration)return;mappings.value=rows.length?rows.map((m:ProviderDraftMapping)=>({logical_model:m.logical_model,upstream_model:m.upstream_model,model_type:m.model_type,status:m.status})):mappings.value;mappingsReady.value=true}catch(e){if(gen===openGeneration)ElMessage.error(message(e))}finally{if(gen===openGeneration)mappingLoading.value=false}}
}
async function discoverDraft(){
  if(!validateUrls())return;const gen=openGeneration;discovering.value=true
  try{const connection:any={name:form.name||'discovery',provider_type:form.provider_type,protocol_type:form.protocol_type,account_type:form.account_type,...connectionConfig(),base_url:connectionBaseUrl(),proxy:form.proxy||null};if(form.api_key)connection.api_key=form.api_key;if(editing.value&&!form.clear_api_key)connection.provider_id=editing.value
  const found=(await api.post('/admin/providers/discover-models',connection)).data.data.models.map((m:{id:string})=>m.id);if(gen!==openGeneration||!dialog.value)return;discovered.value=found;ElMessage.success('发现 '+discovered.value.length+' 个模型')}catch(e){if(gen===openGeneration)ElMessage.error(message(e))}finally{if(gen===openGeneration)discovering.value=false}
}
function changeType(){const t=selectedType.value;if(t){form.account_type='standard';form.protocol=t.protocols.includes('openai')?'openai':t.protocols[0]||'openai';if(!availableCategories.value.some(([k])=>k===form.protocol_type))form.protocol_type=availableCategories.value[0]?.[0]||'text';form.base_url=t.base_url;loadProtocols();discovered.value=[]}}
function changePlan(){form.base_url=plans.value[form.account_type]?.base_url||'';loadProtocols();discovered.value=[]}
function changeCategory(){const previous=Object.fromEntries(Object.entries(routes).map(([p,r])=>[p,{...r}])),urls={...protocolUrls},separate=separateUrls.value;const textual=['text','multimodal'].includes(form.protocol_type||'');if(!(textual&&selectedProtocols.value.every(p=>['openai-completions','openai-responses','anthropic-messages','ollama'].includes(p))))loadProtocols();for(const p of selectedProtocols.value){if(previous[p])routes[p]={...previous[p]};if(urls[p])protocolUrls[p]=urls[p]};separateUrls.value=separate;syncProtocols();discovered.value=[];for(const m of mappings.value){if(textual&&['text','reasoning','multimodal'].includes(m.model_type))m.model_type=form.protocol_type==='multimodal'?'multimodal':m.model_type==='multimodal'?'text':m.model_type;else if(!m.logical_model&&!m.upstream_model)m.model_type=form.protocol_type==='multimodal'?'multimodal':form.protocol_type==='vector'?'embedding':form.protocol_type==='image'?'image':'text'};verifyAfterSave.value=false}
async function openTest(p:Provider){autoTest.value=false;try{testAccount.value=(await api.get('/admin/providers/'+p.id)).data.data;testDialog.value=true}catch(e){ElMessage.error(message(e))}}
watch(()=>mappings.value.map(m=>m.logical_model+'|'+m.status).join(','),()=>{if(mappingsReady.value&&!mappingLoading.value&&form.default_test_model&&!testModels.value.some(m=>m.logical_model===form.default_test_model))form.default_test_model=''})
async function save(){
  if(!form.name.trim()||!form.base_url.trim()){ElMessage.error('请填写账号名称和服务 URL');return}
  if(!validateUrls())return
  if(!selectedProtocols.value.length){ElMessage.error('请至少选择一个协议');return}
  if(form.api_key&&form.clear_api_key){ElMessage.error('不能同时更换和清除 Key');return}
  if(form.default_test_model&&!testModels.value.some(m=>m.logical_model===form.default_test_model)){ElMessage.error('请选择已启用的默认测试模型');return}
  if(verifyAfterSave.value&&(!form.default_test_model||form.status!=='enabled')){ElMessage.error('保存后验证需要启用账号并选择测试模型');return}
  if(!mappingsReady.value||mappingLoading.value)return
  if(!mappings.value.length||mappings.value.length>100||mappings.value.some(m=>!m.logical_model.trim()||!m.upstream_model.trim())){ElMessage.error('请填写1至100条完整模型映射');return}
  if(new Set(mappings.value.map(m=>m.logical_model.trim())).size!==mappings.value.length){ElMessage.error('请求模型名称不能重复');return}
  const categoryOf=(t:string)=>t==='image'?'image':['embedding','rerank'].includes(t)?'vector':'text'
  if(form.protocol_type&&mappings.value.some(m=>(form.protocol_type==='multimodal'?m.model_type:categoryOf(m.model_type))!==form.protocol_type)){ElMessage.error('模型映射类型须与账号协议类型一致');return}
  saving.value=true
  try{
    const payload:any={name:form.name,provider_type:form.provider_type,protocol_type:form.protocol_type,account_type:form.account_type,...connectionConfig(),base_url:connectionBaseUrl(),proxy:form.proxy||null,priority:form.priority,max_concurrency:form.max_concurrency,status:form.status,remark:form.remark,default_test_model:form.default_test_model||null,model_mappings:mappings.value.map(m=>({...m,logical_model:m.logical_model.trim(),upstream_model:m.upstream_model.trim()}))}
    if(editing.value&&editorVersion.value!==null)payload.expected_config_version=editorVersion.value
    if(form.api_key)payload.api_key=form.api_key
    if(editing.value)payload.clear_api_key=form.clear_api_key
    const saved=(editing.value?await api.patch('/admin/providers/'+editing.value,payload):await api.post('/admin/providers',payload)).data.data
    const verify=verifyAfterSave.value;dialog.value=false;form.api_key='';ElMessage.success('账号已保存');await load()
    if(verify){testAccount.value=(await api.get('/admin/providers/'+saved.id)).data.data;autoTest.value=true;testDialog.value=true}
  }catch(e){ElMessage.error(message(e))}finally{saving.value=false}
}
async function toggle(p:Provider){try{await api.patch('/admin/providers/'+p.id,{status:p.status==='enabled'?'disabled':'enabled'});await load()}catch(e){ElMessage.error(message(e))}}
async function remove(p:Provider){try{await ElMessageBox.confirm('删除后账号停止使用，历史记录保留。','删除 '+p.name,{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api.delete('/admin/providers/'+p.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
async function test(p:Provider){testing.value=p.id;try{testResult.value=(await api.post('/admin/providers/'+p.id+'/test')).data.data;await load()}catch(e){ElMessage.error(message(e))}finally{testing.value=null}}
onMounted(async()=>{try{types.value=(await api.get('/admin/providers/types')).data.data}catch(e){error.value=message(e)}await load()});onBeforeUnmount(()=>{form.api_key='';openGeneration++;loadGeneration++})
</script>
<template><div><PageHeader title="模型供应商"><el-button type="primary" @click="open()">新增账号</el-button></PageHeader><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="q" placeholder="搜索账号 / 请求模型 / 上游模型" clearable style="width:240px" @keyup.enter="page=1;load()"/><el-select v-model="status" clearable placeholder="全部状态" style="width:140px"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select><el-select v-model="providerType" clearable placeholder="全部供应商" style="width:150px"><el-option v-for="t in types" :key="t.code" :value="t.code" :label="t.name"/></el-select><el-select v-model="category" clearable placeholder="全部协议类型" style="width:145px"><el-option v-for="(label,value) in categoryLabels" v-show="value!=='mixed'" :key="value" :value="value" :label="label"/></el-select><el-select v-if="advanced" v-model="protocol" clearable placeholder="全部协议" style="width:140px"><el-option v-for="p in protocolNames" :key="p" :label="p" :value="p"/></el-select><el-select v-if="advanced" v-model="health" clearable placeholder="全部健康状态" style="width:155px"><el-option label="未测试" value="unknown"/><el-option label="连接正常" value="healthy"/><el-option label="连接异常" value="unhealthy"/></el-select><el-button @click="page=1;load()">查询</el-button><el-button @click="advanced=!advanced">{{advanced?'收起筛选':'更多筛选'}}</el-button><el-popover trigger="click" width="220"><template #reference><el-button>显示列</el-button></template><el-checkbox-group v-model="visibleColumns"><el-checkbox v-for="(label,key) in columnOptions" :key="key" :value="key">{{label}}</el-checkbox></el-checkbox-group></el-popover></div><el-table :data="rows" v-loading="loading" empty-text="暂无账号，请添加实际模型服务"><el-table-column label="账号" min-width="160"><template #default="s"><router-link :to="'/admin/providers/'+s.row.id" style="color:var(--el-color-primary)">{{s.row.name}}</router-link></template></el-table-column><el-table-column label="供应商 / 协议" min-width="180"><template #default="s">{{typeName(s.row.provider_type)}}<div class="muted">{{s.row.account_type_name}}</div><div class="muted">{{s.row.protocol_config?Object.keys(s.row.protocol_config).join(' / '):s.row.protocol}}</div></template></el-table-column><el-table-column label="协议类型" width="120"><template #default="s">{{categoryLabels[s.row.effective_protocol_type]||'未配置'}}</template></el-table-column><el-table-column v-if="visibleColumns.includes('models')" label="模型" min-width="210"><template #default="s"><div v-for="m in s.row.models.slice(0,3)" :key="m.logical_model"><el-tag size="small" :type="m.status==='enabled'?'':'info'">{{m.logical_model}}</el-tag><span class="muted"> → {{m.upstream_model}}</span></div><el-tooltip v-if="s.row.models.length>3" :content="s.row.models.map((m:ProviderDraftMapping)=>m.logical_model).join(' / ')"><span class="muted">另有 {{s.row.models.length-3}} 个模型</span></el-tooltip></template></el-table-column><el-table-column label="状态" width="85"><template #default="s"><el-switch :model-value="s.row.status" active-value="enabled" inactive-value="disabled" :aria-label="'启用账号 '+s.row.name" :disabled="loading||saving" @change="toggle(s.row)"/></template></el-table-column><el-table-column v-if="visibleColumns.includes('health')" label="健康状态" width="115"><template #default="s"><el-tag :type="s.row.health_status==='healthy'?'success':s.row.health_status==='unhealthy'?'danger':'info'">{{healthLabels[s.row.health_status]}}</el-tag></template></el-table-column><el-table-column v-if="visibleColumns.includes('health')" label="调度状态" width="110"><template #default="s"><el-tag :type="s.row.scheduling_state==='Available'?'success':s.row.scheduling_state==='Cooling'?'warning':s.row.scheduling_state==='Unavailable'?'danger':'info'">{{schedulingLabels[s.row.scheduling_state]}}</el-tag></template></el-table-column><el-table-column v-if="visibleColumns.includes('concurrency')" label="当前 / 最大并发" width="155"><template #default="s">{{s.row.current_concurrency??'未知'}} / {{s.row.max_concurrency}}<el-progress v-if="s.row.current_concurrency!==null" :percentage="Math.min(100,s.row.current_concurrency/s.row.max_concurrency*100)" :show-text="false" :stroke-width="4"/></template></el-table-column><el-table-column v-if="visibleColumns.includes('priority')" prop="priority" label="优先级" width="85"/><el-table-column v-if="visibleColumns.includes('latency')" label="最近延迟" width="110"><template #default="s">{{s.row.last_latency_ms==null?'—':s.row.last_latency_ms+' ms'}}</template></el-table-column><el-table-column v-if="visibleColumns.includes('key')" label="Key" width="90"><template #default="s">{{s.row.has_api_key?'已配置':'未配置'}}</template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="primary" :disabled="s.row.status!=='enabled'" @click="openTest(s.row)">测试</el-button><el-button link :disabled="s.row.status!=='enabled'||testing!==null" :loading="testing===s.row.id" @click="test(s.row)">连接检查</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column><template #empty><EmptyState title="暂无账号，请添加实际模型服务" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" style="margin-top:24px" @current-change="load"/></div><el-drawer v-model="dialog" :title="editing?'编辑账号':'新增账号'" size="860px" @closed="form.api_key='';openGeneration++"><el-form label-width="115px"><el-form-item label="账号名称"><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="供应商"><el-select v-model="form.provider_type" @change="changeType"><el-option v-for="t in types" :key="t.code" :value="t.code" :label="t.name"/></el-select></el-form-item><el-form-item label="账号类型"><el-select v-model="form.account_type" @change="changePlan"><el-option v-for="(plan,key) in plans" :key="key" :value="key" :label="plan.name"/></el-select></el-form-item><el-form-item label="协议类型" required><el-select v-model="form.protocol_type" placeholder="历史混合账号，可选择统一类型" @change="changeCategory"><el-option v-for="[key,label] in availableCategories" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item v-if="selectedType?.description" label="接入说明"><div><p style="margin:0 0 8px;line-height:1.6">{{selectedType.description}}</p><a :href="selectedType.docs_url" target="_blank" rel="noopener noreferrer" style="color:var(--el-color-primary)">查看接入说明</a></div></el-form-item><el-form-item label="服务 URL" required><div style="width:100%"><el-input v-model="form.base_url" placeholder="例如 https://open.bigmodel.cn/api/paas/v4" maxlength="2048"/><p class="muted" style="margin:8px 0">填写完整 API 基础地址，包含 /v1、/api/paas/v4 等路径；请求端点由系统按协议追加。</p><el-checkbox v-model="separateUrls" @change="toggleSeparateUrls">不同协议使用独立服务 URL</el-checkbox><div v-if="separateUrls"><el-form-item v-for="p in selectedProtocols" :key="p" :label="p" label-width="170px" style="margin:12px 0"><el-input v-model="protocolUrls[p]" placeholder="填写此协议的完整 API 基础地址" maxlength="2048"/></el-form-item></div></div></el-form-item><el-form-item label="协议配置" required><div class="protocol-config"><el-select v-model="selectedProtocols" multiple placeholder="选择支持的协议" @change="syncProtocols"><el-option v-for="p in protocolOptions" :key="p" :value="p" :label="p==='ollama'?'ollama（原生）':p"/></el-select><p class="muted">仅选择上游实际支持的协议。所有 API 路径统一在服务 URL 中填写。</p><div v-for="p in selectedProtocols.filter(p=>p==='anthropic-messages')" :key="p" class="protocol-row"><span>{{p}} 鉴权</span><el-select v-if="p==='anthropic-messages'" v-model="routes[p]!.auth_type" class="protocol-auth"><el-option label="x-api-key" value="x-api-key"/><el-option label="Bearer Token" value="bearer"/></el-select></div></div></el-form-item><el-form-item label="API Key"><el-input v-model="form.api_key" type="password" autocomplete="new-password" :placeholder="editing?'留空保留原Key':selectedType?.key_required?'请填写上游Key':'可选，本地服务可不配置'" maxlength="4096"/></el-form-item><el-form-item v-if="editing&&hasKey" label="已有 Key"><span>已配置，完整密钥不可查看</span><el-checkbox v-model="form.clear_api_key" style="margin-left:15px">清除原Key</el-checkbox></el-form-item><div v-loading="mappingLoading"><ProviderMappingEditor v-model="mappings" :models="discovered" :discovering="discovering" :category="form.protocol_type" @discover="discoverDraft"/></div><el-form-item label="默认测试模型"><div style="width:100%"><el-select v-model="form.default_test_model" clearable filterable placeholder="可选：从已启用的模型映射中选择"><el-option v-for="m in testModels" :key="m.logical_model" :value="m.logical_model" :label="m.logical_model+' → '+m.upstream_model"/></el-select><p class="muted" style="margin:8px 0 0">在测试弹窗中默认选中此模型；连接检查仅核对上游模型列表，不验证生成能力。</p></div></el-form-item><el-form-item v-if="form.protocol_type!=='image'" label="保存验证"><el-checkbox v-model="verifyAfterSave" :disabled="form.status!=='enabled'">保存后真实调用默认测试模型，可能产生用量和费用</el-checkbox></el-form-item><el-form-item label="HTTP代理"><el-input v-model="form.proxy" placeholder="可选：http://代理地址:端口" maxlength="2048"/></el-form-item><el-form-item label="优先级"><el-input-number v-model="form.priority" :min="0" :max="100000" :precision="0"/><span class="muted" style="margin-left:12px">数值越小越优先；相同优先级按负载调度。</span></el-form-item><el-form-item label="最大并发"><el-input-number v-model="form.max_concurrency" :min="1" :max="100000" :precision="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="2000"/></el-form-item><p class="muted">连接检查只读取模型列表。真实调用请使用“测试”；文生图保存时不会生成图片。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="mappingLoading||!mappingsReady" @click="save">保存</el-button></template></el-drawer><el-dialog :model-value="!!testResult" title="连接检查结果" width="580px" @close="testResult=null"><template v-if="testResult"><el-alert :title="testResult.message" :type="testResult.success?'success':'error'" :closable="false"/><el-descriptions :column="2" border style="margin-top:20px"><el-descriptions-item label="网络">{{testResult.network_connected?'已连接':'未确认连接'}}</el-descriptions-item><el-descriptions-item label="鉴权">{{authLabels[testResult.authentication]}}</el-descriptions-item><el-descriptions-item label="HTTP状态">{{testResult.http_status??'无响应'}}</el-descriptions-item><el-descriptions-item label="响应时间">{{testResult.latency_ms}} ms</el-descriptions-item><el-descriptions-item label="返回模型数">{{testResult.model_count??'未取得'}}</el-descriptions-item><el-descriptions-item v-if="testResult.test_model" label="测试模型">{{testResult.test_model}} · {{testResult.model_available?'已发现':'未发现'}}</el-descriptions-item><el-descriptions-item label="错误代码">{{testResult.error_code||'无'}}</el-descriptions-item></el-descriptions></template></el-dialog><ProviderTestDialog v-model="testDialog" :provider="testAccount" :auto-start="autoTest" @finished="load"/></div></template>



<style scoped>.protocol-config{width:100%}.protocol-row{display:flex;align-items:center;gap:12px;margin-top:12px}.protocol-row>span{width:185px;flex-shrink:0;color:var(--el-text-color-primary)}.protocol-row>.el-input{flex:1}.protocol-auth{width:155px!important;flex-shrink:0}@media(max-width:700px){.protocol-row{flex-wrap:wrap}.protocol-row>span{width:100%}}</style>
